#!/usr/bin/env node
// Generates the renderers' design tokens from design/tokens.json
// (docs/design/UNIFIED_UI.md 5, 6).
//
//   node tools/gen_tokens.mjs            writes src/ui/ui_tokens.h
//   node tools/gen_tokens.mjs --check    fails when a generated file is stale (CI)
//
// Structure: resolveTokens() turns the JSON into a renderer-neutral model
// (named values per theme); each output is an emitter over that model. A C
// header emitter (src/ui/ui_tokens.h, U3) adds another emitter and a target
// below; nothing else changes.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const tokens = JSON.parse(readFileSync(resolve(root, 'design/tokens.json'), 'utf8'));

// The host theme (docs/design/UNIFIED_UI.md 6): the card is the host's, so the
// surfaces and the line are foreground alphas over it, and text and the UI
// font inherit. The heat scale stays ours; they use mid-tone
// values that read on a dark and on a light card.
const HOST_COLORS = {
  ...tokens.color.host,
  // The wrapper sets these from the host's palette; these are the fallbacks
  // (the status colors that are text are in the host block, mixed with the card's text).
  accent: tokens.color.light.accent,
  ok: tokens.color.light.ok,
  info: tokens.color.light.info,
};

function resolveTokens(t) {
  // The tile fill is data (the view carries the stops) and there is no
  // hatching: one flat disabled look (docs/design/UNIFIED_UI.md 4a).
  const themes = {
    dark: { ...t.color.dark },
    light: { ...t.color.light },
    host: { ...HOST_COLORS },
  };
  const ui = `"${t.font.ui}", ui-sans-serif, system-ui, sans-serif`;
  const mono = `ui-monospace, "Roboto Mono", monospace`;
  const monoStandalone = `"${t.font.mono}", ${mono}`;
  return {
    themes,
    // undefined in the host theme: the component falls back to `inherit`.
    fonts: { host: { mono }, dark: { ui, mono: monoStandalone }, light: { ui, mono: monoStandalone } },
    radius: t.radius,
    hatch: t.hatch,
    space: t.space,
    type: t.type.web,
    typeDevice: t.type.device,
    tile: t.tile,
  };
}

// ---- emitters -------------------------------------------------------------

function cssBlock(selector, decls) {
  return `${selector} {\n${decls.map(([k, v]) => `  ${k}: ${v};`).join('\n')}\n}\n`;
}

function emitCss(m) {
  const out = ['/* Generated by tools/gen_tokens.mjs from design/tokens.json. Do not edit. */\n'];
  const shared = [];
  for (const [k, v] of Object.entries(m.radius)) shared.push([`--oams-radius-${k}`, `${v}px`]);
  for (const [k, v] of Object.entries(m.space)) if (typeof v === 'number') shared.push([`--oams-gap-${k}`, `${v}px`]);
  shared.push(['--oams-hatch-angle', `${m.hatch.angle}deg`], ['--oams-hatch-period', `${m.hatch.period}px`],
    ['--oams-hatch-stripe', `${m.hatch.stripe}px`]);
  for (const [k, [size, weight]] of Object.entries(m.type)) {
    shared.push([`--oams-fs-${k}`, `${size}px`], [`--oams-fw-${k}`, String(weight)]);
  }
  shared.push(['--oams-ink-threshold', String(m.tile.ink_threshold)]);
  const themeDecls = (name) => {
    // "$comment" (and any "$" key) in design/tokens.json is documentation, not a
    // token: emitted as a property it is invalid CSS, and its prose (an apostrophe
    // inside a parenthesis) swallows the declarations after it.
    const d = Object.entries(m.themes[name])
      .filter(([k]) => !k.startsWith('$'))
      .filter(([k]) => name !== 'host' || k !== 'text')
      .map(([k, v]) => [`--oams-${k}`, v]);
    d.push(['--oams-hatch-alpha', `${Math.round(m.hatch.alpha[name] * 100)}%`]);
    if (m.fonts[name].ui) d.push(['--oams-font-ui', m.fonts[name].ui]);
    d.push(['--oams-font-mono', m.fonts[name].mono]);
    return d;
  };
  // theme="host" is the default (and the fallback for any other value).
  out.push(cssBlock(':host', [...shared, ...themeDecls('host')]));
  out.push(cssBlock(':host([theme="dark"])', themeDecls('dark')));
  out.push(cssBlock(':host([theme="light"])', themeDecls('light')));
  return out.join('\n');
}

// ---- C header (src/ui/ui_tokens.h, the LVGL renderer) ---------------------

// "surface-1" -> UI_TOK_SURFACE_1, "tile-label" -> UI_TOK_TILE_LABEL.
const cIdent = (k) => k.replace(/-/g, '_').toUpperCase();

// "#rrggbb" or "rgba(r,g,b,a)". LVGL carries opacity on the style, not in the
// color, so a translucent token becomes a color plus a matching _OPA in
// 0..255; an opaque one becomes the color alone.
function parseColor(v) {
  const rgba = /^rgba\(([^)]+)\)$/.exec(v);
  if (rgba) {
    const [r, g, b, a] = rgba[1].split(',').map((s) => parseFloat(s));
    return { hex: [r, g, b], opa: Math.round(a * 255) };
  }
  const n = parseInt(v.slice(1), 16);
  return { hex: [(n >> 16) & 255, (n >> 8) & 255, n & 255], opa: 255 };
}

function emitCHeader(m) {
  const out = [
    '/*',
    ' * ui_tokens.h - the device\'s design tokens.',
    ' *',
    ' * Generated by tools/gen_tokens.mjs from design/tokens.json. Do not edit.',
    ' * (docs/design/UNIFIED_UI.md 5, 6: the device compiles in the dark set.)',
    ' *',
    ' * The restyled home screen draws with these and nothing else; the screens',
    ' * that predate the design system keep using ui_theme.h.',
    ' */',
    '',
    '#ifndef UI_TOKENS_H',
    '#define UI_TOKENS_H',
    '',
    '#include "lvgl.h"',
    '',
    '/* ------------------------------------------------------------- color */',
    '',
  ];
  for (const [k, v] of Object.entries(m.themes.dark)) {
    const { hex, opa } = parseColor(v);
    const id = `UI_TOK_${cIdent(k.replace(/-/g, '_'))}`;
    out.push(`#define ${(id + ' ').padEnd(24)}lv_color_hex(0x${hex.map((n) => n.toString(16).padStart(2, '0')).join('').toUpperCase()})`);
    if (opa < 255) out.push(`#define ${(id + '_OPA ').padEnd(24)}${opa} /* was ${v} */`);
  }
  out.push('', '/* ------------------------------------------------------------ radius */', '');
  for (const [k, v] of Object.entries(m.radius)) {
    out.push(`#define ${(`UI_TOK_RADIUS_${cIdent(k)} `).padEnd(24)}${v}`);
  }
  out.push('', '/* ------------------------------------------------------------- space */', '');
  for (const [k, v] of Object.entries(m.space)) {
    if (typeof v !== 'number') continue;
    out.push(`#define ${(`UI_TOK_SPACE_${cIdent(k)} `).padEnd(24)}${v}`);
  }
  out.push('', '/* --------------------------------------------- hatch (4c, one disabled look) */', '');
  out.push(`#define UI_TOK_HATCH_PERIOD${' '.repeat(14)}${m.hatch.period}`);
  out.push(`#define UI_TOK_HATCH_STRIPE${' '.repeat(13)}${m.hatch.stripe}`);
  out.push(`#define UI_TOK_HATCH_ALPHA${' '.repeat(14)}${Math.round(m.hatch.alpha.dark * 255)}`);
  out.push('', '/* ------------------------------------------------ type.device sizes */', '');
  out.push('/* The weight is the face tools/gen_fonts.py already generated: 600 is');
  out.push(' * semibold for Geist, 500 medium, 400 regular. */');
  for (const [k, [size, weight]] of Object.entries(m.typeDevice)) {
    out.push(`#define ${(`UI_TOK_FONT_${cIdent(k)} `).padEnd(24)}${size}`);
    out.push(`#define ${(`UI_TOK_WEIGHT_${cIdent(k)} `).padEnd(24)}${weight}`);
  }
  out.push('', '#endif /* UI_TOKENS_H */', '');
  return out.join('\n');
}

const targets = [
  { path: 'src/ui/ui_tokens.h', emit: emitCHeader },
];

const model = resolveTokens(tokens);
const check = process.argv.includes('--check');
let stale = 0;
for (const { path, emit } of targets) {
  const file = resolve(root, path);
  const text = emit(model);
  if (check) {
    let have = null;
    try { have = readFileSync(file, 'utf8'); } catch { /* missing counts as stale */ }
    if (have !== text) { console.error('stale:', path); stale++; }
    continue;
  }
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, text);
  console.log('wrote', path);
}
if (check) {
  if (stale) { console.error('run: node tools/gen_tokens.mjs'); process.exit(1); }
  console.log('tokens: generated files are current');
}
